INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1536361-che212', 'stk-giant_genius1', 'CHE 212', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته\n\nبعد إذن الأخوة المشرفين\n\nيا ليت تعطونا فكرة عن المادة و طبيعتها و وش تدرسون فيها\n\nو اللي عنده أي ملف سواء سلايدات او اختبارات قديمة اوهومورك او كويز او اي شي غيرها ممكن يساعدنا يا ليت ينزله لنا هنا و لا عليكم أمر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-212-introduction-to-chemical-engineering-computing/184930/1", "user": "Giant_Genius1", "ts": 1676255582000, "tid": 184930, "pn": 1}}', 1676255582000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-che212', 'stk-ahmed1', 'CHE 212', 'doc', '{"docs": [{"id": "stk-dr-f118698", "n": "Dr. Nayef Al-Saifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 212 - TERM 213\n\nالتحضير : احيانا و يكون بداية الكلاس يناديك اول 5 دقايق و احيانا اول ما يبدأ الكلاس على طول وما يحب التأخير، جزاه الله خير اخر الترم حذف ثلاث غيابات من كل طالب.\n\nطريقة الشرح : ممتازة وواضحة جدا ويخليك تشتغل بنفسك في الكلاس عشان تتعلم.\n\nالكويزات : سهلة الى متوسطة، والمادة سهلة اصلا فما صعبها ابدا.\n\nالمياجر: كان عنده تست واحد وكان جدا سهل ومشابه للي خذناه في الكلاس\nالفاينلات : نفس الشي سهل جدا\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : غير انه الكورس جدا سهل عطانا تاسك نسويه وناخذ بونص عليه، ختاما الدكتور جدا رهيب وقامة علمية كبيرة و تعامله جدا راقي اذا شفته في اي كورس نزل عنده على طول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535054-che212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nayef-al-saifi/118698/30", "user": "Ahmed1", "ts": 1660775363000, "tid": 118698, "pn": 30}}]}', 1660775363000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-che212', 'stk-saleh_h', 'CHE 212', 'doc', '{"docs": [{"id": "stk-dr-f176820", "n": "Dr. Farrukh Shehzad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 212 - Term 212\n\nالتحضير : يحضر كل كلاس بعد اول ربع ساعة ويبدا لما يكتمل العدد\nطريقة الشرح : شرحه جيد لكنه سريع ومستعجل ويكره الاسئلة المتكررة لكن السلايدات سيئة جدًا وتقدر تقول هو افضل من يشرحها.\nالكويزات : متوسطة إلى صعبة\nالمياجر: ميد تيرم وكان صعب صراحة خصوصًا جزئية MATLAB.\nالفاينلات : الفاينل كان سهل جدًا وكان على اسبن فقط.\nالقريد النهائي: B+\nالصوت: واضح جدًا ولهجته مفهومة.\nإضافات : الدكتور محترم ومتساعد لكن يكره ان الطالب ما يركز معه ثم يسأل عن جزئية شرحها الدكتور قبلها بشوي ومستعجل بحل الامثلة فلازم تكتب معه اول باول عشان ما تضيع، ونصيحة ادخل كويزاته كانك داخل لميجر لانه يجيب اسئلته من الاشياء اللي ما يركز عليها الطلاب وعشان كذا كان افرج سكاشنه حول ٥٥٪؜ بالاضافة ان القريدر حقه كان تصحيحه مجحف ويخسف ف تحتاج تراجع الدكتور عشان يعدل الدرجة… عموما الدكتور خيار ممتاز للكورس لكن شد حيلك عنده وموفقين ان شاء الله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534505-che212", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/farrukh-shehzad/176820/2", "user": "Saleh_H", "ts": 1653849221000, "tid": 176820, "pn": 2}}]}', 1653849221000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
